import {normalize,matches,validateBackup,mergeBackup} from './research-core.mjs';
const $=id=>document.getElementById(id),fa=n=>Number(n).toLocaleString('fa-IR');
const KEY='mansour-research-v1';
let personal={format:KEY,notes:[],bookmarks:[]};
let preferences={surah:1,verse:1,dark:false,font:19,spacing:2.15,layout:'side'};
let startupWarning='';
try{const raw=localStorage.getItem(KEY);if(raw)personal=validateBackup(JSON.parse(raw));const p=JSON.parse(localStorage.getItem(KEY+'-prefs')||'{}');preferences={...preferences,...p};}catch{startupWarning='ذخیرهٔ قبلی قابل خواندن نیست. پیش از ذخیرهٔ جدید، فایل پشتیبان خود را بررسی کنید.';}
let content,catalog,noorManifest,offlineManifest,selected,tab='tafsir',activeView='reader',renderTicket=0,libraryLimit=36,bookMatches=[],mizanCatalog,mizanRows=[],mizanTicket=0;
const cache=new Map(),drafts=new Map();
const titles={reader:'مطالعه، در کنار پژوهش',library:'کتابخانهٔ پژوهشی منصور',mizan:'کتاب‌خوان المیزان',notes:'دفتر پژوهش',settings:'تنظیمات نمایش',sources:'منابع و پوشش محتوا'};
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4000);}
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function plain(value){const parsed=new DOMParser().parseFromString(String(value??''),'text/html');parsed.querySelectorAll('script,style').forEach(e=>e.remove());parsed.querySelectorAll('br').forEach(e=>e.replaceWith('\n'));return parsed.body.textContent||'';}
function remember(){try{localStorage.setItem(KEY+'-prefs',JSON.stringify(preferences));}catch{toast('تنظیمات ذخیره نشد؛ فضای ذخیره‌سازی را بررسی کنید.');}}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));personal=next;return true;}catch{toast('ذخیره نشد؛ از یادداشت‌ها پشتیبان بگیرید و فضای ذخیره‌سازی را بررسی کنید.');return false;}}
async function data(url,optional=false){if(!cache.has(url))cache.set(url,fetch(url).then(r=>{if(!r.ok)throw Error(`فایل در دسترس نیست: ${url}`);return r.json();}).catch(e=>{cache.delete(url);throw e}));try{return await cache.get(url);}catch(e){if(optional)return null;throw e;}}
function option(value,text){const o=el('option',text);o.value=value;return o;}
function currentLabel(a=selected){return `${content.surahs.find(s=>s.id===a.surah_id)?.name_ar}، آیهٔ ${fa(a.number)}`;}
function setView(view){activeView=view;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==view);document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('page-title').textContent=titles[view];if(view==='library')renderLibrary();if(view==='notes')renderNotes();if(view==='sources')renderSources();if(view==='mizan'&&!mizanCatalog)loadMizan().catch(e=>toast(e.message));}
function setSurah(id,verse=1){const surah=content.surahs.find(s=>s.id===Number(id))||content.surahs[0];$('surah').value=surah.id;$('verse').replaceChildren(...Array.from({length:surah.ayah_count},(_,i)=>option(i+1,fa(i+1))));$('verse').value=Math.min(Math.max(1,Number(verse)||1),surah.ayah_count);selectVerse();}
function selectVerse(){selected=content.ayahs.find(a=>a.surah_id===Number($('surah').value)&&a.number===Number($('verse').value));$('juz-jump').value=selected.juz;$('page-jump').value=selected.page;preferences.surah=selected.surah_id;preferences.verse=selected.number;remember();$('quran-text').textContent=selected.text_original;$('surah-title').textContent=`سورهٔ ${content.surahs.find(s=>s.id===selected.surah_id).name_ar}`;$('verse-meta').textContent=`آیهٔ ${fa(selected.number)} · جزء ${fa(selected.juz)} · صفحهٔ ${fa(selected.page)}`;$('location').textContent=currentLabel();$('bookmark').textContent=personal.bookmarks.includes(selected.id)?'★ نشان‌شده':'☆ نشان';$('note-text').value=drafts.get(selected.id)??personal.notes.find(n=>n.ayahId===selected.id)?.text??'';$('prev').disabled=selected.id===1;$('next').disabled=selected.id===6236;const src=`audio/minshawi/${String(selected.surah_id).padStart(3,'0')}.mp3`;if($('audio').getAttribute('src')!==src)$('audio').src=src;renderTranslation();renderResearch();}
let translationTicket=0;
async function renderTranslation(){const ticket=++translationTicket,a=selected,choice=$('translation').value;let text='',footnotes='';try{if(choice.startsWith('noor:')){const d=await data(`research-data/${a.surah_id}.json`);text=(d.translations[a.number]||[]).find(t=>String(t.bookId)===choice.slice(5))?.text||'ترجمه‌ای برای این آیه در این منبع ثبت نشده است.';}else{const e=content.books.find(b=>b.id===choice)?.entries.find(e=>e.ayah_id===a.id);text=e?.text||'ترجمه در دسترس نیست.';footnotes=e?.footnotes||'';}if(ticket!==translationTicket)return;$('translation-text').textContent=plain(text);$('translation-footnotes').textContent=plain(footnotes);}catch(e){if(ticket===translationTicket)$('translation-text').textContent=e.message;}}
function empty(text){return el('div',text,'empty');}
async function renderResearch(){const ticket=++renderTicket,a=selected,which=tab;$('research-body').replaceChildren(el('p','در حال خواندن منبع…','footnote'));$('tafsir-controls').hidden=which!=='tafsir';try{let node;if(which==='references'){const d=await data(`research-data/${a.surah_id}.json`),refs=d.references[a.number]||[];node=el('div');node.append(el('p',`${fa(refs.length)} ارجاع در منصور؛ این بخش نشانی منبع است، نه متن کامل آن.`, 'footnote'));for(const r of refs){const card=el('article',undefined,'ref-card');card.append(el('h3',r.title||'عنوان ثبت‌نشده'),el('p',`جلد ${r.volume??'—'} · صفحهٔ ${r.page??'—'} · بند ${r.startParagraph??'—'}`));const id=String(r.automation).padStart(5,'0'),book=catalog.find(b=>b.id===id);if(book){const btn=el('button','نمایش در فهرست کتابخانه');btn.onclick=()=>{$('library-search').value=book.title;setView('library');};card.append(btn);}node.append(card);}if(!refs.length)node.append(empty('برای این آیه ارجاعی در دادهٔ واردشده ثبت نشده است.')); }else if(which==='related'){
 const d=await data('offline/similarity/'+a.surah_id+'.json',true),rows=d?.[a.number]||[];node=el('div');
 node.append(el('p','پیوندهای ثبت‌شده در بستهٔ آفلاین منصور؛ این فهرست ممکن است کامل نباشد. عدد همراه هر پیوند، مقدار ثبت‌شده در منبع است و لزوماً درصد شباهت نیست.','footnote'));
 const filter=el('input');filter.placeholder='جست‌وجو در آیات مرتبط یا نام سوره…';filter.setAttribute('aria-label','جستجوی آیات مرتبط');filter.className='wide-input';const list=el('div');
 const render=()=>{list.replaceChildren();let count=0;for(const r of rows){const target=content.ayahs.find(v=>v.id===r.id);if(!target||!matches(currentLabel(target)+' '+target.text_original,filter.value))continue;count++;const card=el('article',undefined,'related-card ref-card'),go=el('button','مطالعهٔ آیه');go.onclick=()=>{setSurah(target.surah_id,target.number);window.scrollTo(0,0)};card.append(el('h3',currentLabel(target)),el('p',target.text_original,'source-text'),el('small','مقدار ثبت‌شده: '+fa(r.p)+' · کد نوع ارتباط: '+fa(r.type)),go);list.append(card)}if(!count)list.append(empty('پیوندی با این مشخصات در بستهٔ موجود نیست.'))};filter.oninput=render;render();node.append(filter,list);
 }else if(which==='hadith'){
const d=await data(`offline/hadith/${a.surah_id}.json`,true);node=el('div');node.append(el('p','گزیدهٔ موجود در بستهٔ منصور؛ حداکثر ۸ مورد برای هر آیه. این مجموعه ادعای پوشش کامل ندارد.','footnote'));const rows=d?.[a.number]||[];for(const r of rows){const card=el('article',undefined,'excerpt');card.append(el('h3',r.title||'روایت'),el('div',plain(r.text),'source-text'),el('p',`جلد ${r.volume??'—'} · صفحهٔ ${r.page??'—'} · بستهٔ آفلاین منصور`,'citation'));node.append(card);}if(!rows.length)node.append(empty('روایتی برای این آیه در بستهٔ موجود نیست.'));}else{const ids=[$('tafsir-one').value,$('tafsir-two').value].filter(Boolean);node=el('div',undefined,`tafsir-columns${ids.length>1?' comparing':''}`);for(const id of ids)node.append(await tafsirColumn(id,a));}if(ticket===renderTicket)$('research-body').replaceChildren(node);}catch(e){if(ticket===renderTicket)$('research-body').replaceChildren(empty(e.message));}}
async function tafsirColumn(id,a){const section=el('section'),header=el('div',undefined,'source-heading');const name=id==='moyassar'?'التفسير الميسر':offlineManifest.books[id];header.append(el('h3',name),el('span','متن موجود','source-tag'));section.append(header);if(id==='moyassar'){const book=content.books.find(b=>b.id===id),entry=book?.entries.find(e=>e.ayah_id===a.id);section.append(el('div',plain(entry?.text||'متن موجود نیست.'),'source-text'));if(entry?.footnotes)section.append(el('p',plain(entry.footnotes),'footnote'));section.append(el('p',`${book?.author||''} · QuranEnc · نسخهٔ ${book?.version||'ثبت‌نشده'}`,'citation'));return section;}const d=await data(`offline/tafsir/${id}/${a.surah_id}.json`,true),rows=d?.[a.number]||[];section.append(el('p','گزیده‌های ذخیره‌شدهٔ مرتبط با آیه؛ ممکن است از میانهٔ صفحه آغاز شوند.','footnote'));for(const group of rows){for(const p of group.pages||[]){const block=el('article',undefined,'excerpt');block.append(el('div',plain(p.text),'source-text'),el('p',`${group.title||name} · جلد ${group.volume??'—'} · صفحهٔ ${p.page??'—'}`,'citation'));section.append(block);}}if(!rows.length)section.append(empty('برای این آیه متنی در این بسته موجود نیست. منبع دیگری یا بخش ارجاعات منصور را بررسی کنید.'));return section;}
function renderLibrary(){const query=$('library-search').value;bookMatches=catalog.filter(b=>matches([b.title,b.author,b.publisher,...b.subjects].join(' '),query)&&(!$('library-language').value||b.languages.includes($('library-language').value))&&(!$('library-subject').value||b.subjects.includes($('library-subject').value)));const sort=$('library-sort').value;if(sort!=='default')bookMatches.sort((a,b)=>(a[sort]||'').localeCompare(b[sort]||'','fa'));$('library-count').textContent=`${fa(bookMatches.length)} مجموعه از ${fa(catalog.length)} مجموعه`;$('library-list').replaceChildren();for(const b of bookMatches.slice(0,libraryLimit)){const card=el('article',undefined,'book-card'),body=el('div');card.append(el('div','ک','book-icon'),body);body.append(el('h3',b.title),el('p',b.author||'نویسنده ثبت نشده'),el('small',`${fa(b.volumes||0)} جلد · فقط شناسنامه`));const details=el('details');details.append(el('summary','شناسنامهٔ بیشتر'),el('p',`ناشر: ${b.publisher||'نامشخص'}`),el('p',`موضوع: ${b.subjects.join('، ')||'ثبت نشده'}`),el('p',`شناسهٔ منبع: ${b.id}`));body.append(details);$('library-list').append(card);}$('more-books').hidden=bookMatches.length<=libraryLimit;if(!bookMatches.length)$('library-list').append(empty('کتابی با این عبارت پیدا نشد.'));}
function renderNotes(){const query=$('notes-search').value;$('bookmarks-list').replaceChildren();for(const id of personal.bookmarks){const a=content.ayahs.find(a=>a.id===id);if(!a)continue;const b=el('button',currentLabel(a));b.onclick=()=>{setSurah(a.surah_id,a.number);setView('reader')};$('bookmarks-list').append(b);}if(!personal.bookmarks.length)$('bookmarks-list').append(empty('هنوز آیه‌ای نشان نشده است.'));$('notes-list').replaceChildren();const notes=personal.notes.filter(n=>matches(n.text,query));for(const note of notes){const a=content.ayahs.find(a=>a.id===note.ayahId);if(!a)continue;const card=el('article',undefined,'note-card'),actions=el('div',undefined,'note-actions'),go=el('button','بازگشت به آیه'),del=el('button','حذف');go.onclick=()=>{setSurah(a.surah_id,a.number);setView('reader')};del.onclick=()=>{if(confirm('این یادداشت حذف شود؟')&&persist({...personal,notes:personal.notes.filter(n=>n.id!==note.id)})){drafts.delete(note.ayahId);renderNotes();}};actions.append(go,del);card.append(el('h3',currentLabel(a)),el('p',note.text),actions);$('notes-list').append(card);}if(!notes.length)$('notes-list').append(empty('یادداشتی برای نمایش وجود ندارد.'));}
function renderSources(){const root=$('sources-list');root.replaceChildren();const overview=el('article',undefined,'source-card');overview.append(el('h3','ترکیب داده‌های واقعی'),el('p',`قرآن: ${fa(content.surahs.length)} سوره و ${fa(content.ayahs.length)} آیه. فهرست منصور: ${fa(catalog.length)} مجموعه. ارجاعات تفسیری منصور: ${fa(noorManifest.referenceCount)} رکورد در بانک منابع.`),el('p','این کتابخانه، متن‌های موجود و ارجاعات پژوهشی را در یک محیط گردآوری می‌کند. منشأ داده‌ها و شرایط استفاده در پروندهٔ منابع همراه برنامه ثبت شده است.'),el('p','برخی بسته‌های تفسیری فقط گزیده دارند؛ فهرست منصور به معنی همراه‌بودن متن کامل ۹۰۳ کتاب نیست. ریشه‌شناسی، تحلیل نحوی و جست‌وجوی جامع همهٔ تفاسیر هنوز در میز جدید پیاده‌سازی نشده‌اند.'));root.append(overview);for(const s of content.sources){const card=el('article',undefined,'source-card');card.append(el('h3',s.title||s.id),el('p',s.license_name||'مجوز در داده مشخص نشده'),el('p',s.url||''));const details=el('details');details.append(el('summary','متن مجوز ثبت‌شده'),el('p',s.license_text||'در بستهٔ ورودی متنی ثبت نشده است.'));card.append(details);root.append(card);}const assets=el('article',undefined,'source-card');assets.append(el('h3','فونت‌ها، صوت و دیگر محتواهای منصور'),el('p','فونت‌ها و اعلامیه‌های مجوز همراه بسته حفظ شده‌اند. فایل‌های صوت، المیزان، احادیث و گزیده‌های تفسیری از بستهٔ نصب‌شدهٔ خودتان آمده‌اند؛ اعتبارسنجی علمی و مدارک مجوز انتشار هر بسته باید در فرایند انتشار نهایی ثبت شود.'));root.append(assets);}
let searchTicket=0;
async function search(){const query=$('search').value.trim();if(!query){$('search-results').hidden=true;return;}const ticket=++searchTicket,result=$('search-results');result.hidden=false;result.replaceChildren(el('p','در حال جست‌وجو…'));await new Promise(r=>setTimeout(r,0));const books=content.books.map(b=>({book:b,entries:new Map(b.entries.map(e=>[e.ayah_id,e]))}));const hits=[];for(const a of content.ayahs){const fields=[{name:'قرآن',text:a.text_original},...books.map(b=>({name:b.book.title,text:b.entries.get(a.id)?.text||''}))];const hit=fields.find(f=>matches(f.text,query));if(hit)hits.push({ayah:a,hit});}if(ticket!==searchTicket)return;result.replaceChildren(el('p',`${fa(hits.length)} نتیجه در قرآن، ترجمهٔ رواد و تفسیر میسر؛ نمایش حداکثر ۱۰۰ نتیجه. جست‌وجو به اعراب و شکل ی/ک حساس نیست.`,'footnote'));const close=el('button','بستن نتایج');close.onclick=()=>result.hidden=true;result.append(close);for(const {ayah:a,hit}of hits.slice(0,100)){const b=el('button',undefined,'search-item');b.append(el('small',`${currentLabel(a)} · ${hit.name}`),el('p',hit.text.length>280?hit.text.slice(0,280)+'…':hit.text));b.onclick=()=>{setSurah(a.surah_id,a.number);result.hidden=true;};result.append(b);}if(!hits.length)result.append(empty('نتیجه‌ای پیدا نشد.'));}
async function loadMizan(){mizanCatalog=await data('almizan/catalog.json');$('mizan-volume').replaceChildren(...mizanCatalog.volumes.map(v=>option(v.volume,`جلد ${fa(v.volume)}`)));await loadMizanVolume();}
async function loadMizanVolume(){const ticket=++mizanTicket,volume=Number($('mizan-volume').value);$('mizan-text').textContent='در حال خواندن جلد…';const rows=await data(`almizan/${volume}.json`);if(ticket!==mizanTicket)return;mizanRows=rows;const pages=[...new Set(rows.map(r=>r.pdfPage))].sort((a,b)=>a-b);$('mizan-page').replaceChildren(...pages.map(p=>option(p,fa(p))));renderMizanPage();}
function renderMizanPage(){const page=Number($('mizan-page').value);$('mizan-text').textContent=mizanRows.filter(r=>r.pdfPage===page).map(r=>plain(r.text)).join('\n\n');$('mizan-prev').disabled=$('mizan-page').selectedIndex<=0;$('mizan-next').disabled=$('mizan-page').selectedIndex>=$('mizan-page').options.length-1;}
async function copyText(text){if(window.MansourAndroid){window.MansourAndroid.copyText(text);return;}await navigator.clipboard.writeText(text);}
window.jameBack=()=>{if(!$('search-results').hidden){$('search-results').hidden=true;return true;}if(activeView!=='reader'){setView('reader');return true;}return false;};
function download(name,body,type){if(window.MansourAndroid){window.MansourAndroid.saveDocument(name,body,type);return;}const url=URL.createObjectURL(new Blob([body],{type})),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}

const themes=[['emerald','سبز منصور','#1c6958'],['sky','آبی آسمانی','#245b93'],['sepia','کاغذ کرم','#76502d'],['rose','ارغوانی','#803f68'],['night','شب','#8bd2b2'],['contrast','کنتراست بالا','#ffe600']];
function applyAppearance(){
 if(!themes.some(t=>t[0]===preferences.theme))preferences.theme=preferences.dark?'night':'emerald';
 preferences.font=Math.min(28,Math.max(15,Number(preferences.font)||19));
 preferences.spacing=[1.9,2.15,2.6].includes(Number(preferences.spacing))?Number(preferences.spacing):2.15;
 preferences.layout=preferences.layout==='stack'?'stack':'side';
 preferences.dark=['night','contrast'].includes(preferences.theme);
 document.body.classList.toggle('dark',preferences.dark);document.body.dataset.theme=preferences.theme;document.body.dataset.layout=preferences.layout;
 document.documentElement.style.setProperty('--reading',preferences.font+'px');document.documentElement.style.setProperty('--spacing',preferences.spacing);
 $('theme').querySelector('span').textContent=preferences.dark?'حالت روز':'حالت شب';
 $('setting-font').value=preferences.font;$('font-value').textContent=fa(preferences.font);$('setting-spacing').value=preferences.spacing;$('setting-layout').value=preferences.layout;
 document.querySelectorAll('[data-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.choice===preferences.theme)));
}
for(const [id,title,color] of themes){const b=el('button',title,'theme-choice');b.dataset.choice=id;const swatch=el('span');swatch.style.background=color;b.prepend(swatch);b.onclick=()=>{preferences.theme=id;applyAppearance();remember()};$('theme-choices').append(b);}
for(const [id,key] of [['setting-font','font'],['setting-spacing','spacing'],['setting-layout','layout']])$(id).oninput=()=>{preferences[key]=$(id).value;applyAppearance();remember()};

async function init(){[content,catalog,noorManifest,offlineManifest]=await Promise.all([data('content.json'),data('research-data/catalog.json'),data('research-data/manifest.json'),data('offline/manifest.json')]);if(content.surahs.length!==114||content.ayahs.length!==6236)throw Error('شمارش متن قرآن معتبر نیست.');$('surah').replaceChildren(...content.surahs.map(s=>option(s.id,`${fa(s.id)} · ${s.name_ar}`)));$('translation').replaceChildren(...content.books.filter(b=>b.kind==='translation').map(b=>option(b.id,b.title)),...noorManifest.translationBooks.map(b=>option(`noor:${b.id}`,b.title)));const choices=[['moyassar','التفسير الميسر'],...Object.entries(offlineManifest.books)];$('tafsir-one').replaceChildren(...choices.map(([id,title])=>option(id,title)));$('tafsir-two').replaceChildren(option('','بدون مقایسه'),...choices.map(([id,title])=>option(id,title)));$('tafsir-one').value='317';$('tafsir-two').value='21';applyAppearance();
 $('juz-jump').replaceChildren(...Array.from({length:30},(_,i)=>option(i+1,fa(i+1))));
 for(const [id,field,label] of [['library-language','languages','همهٔ زبان‌ها'],['library-subject','subjects','همهٔ موضوع‌ها']]){$(id).replaceChildren(option('',label),...[...new Set(catalog.flatMap(b=>b[field]))].sort((a,b)=>a.localeCompare(b,'fa')).map(v=>option(v,field==='languages'?({fa:'فارسی',ar:'عربی',en:'انگلیسی',ur:'اردو'}[v]||v):v)));$(id).onchange=()=>{libraryLimit=36;renderLibrary()};}
 setSurah(preferences.surah,preferences.verse);$('loading').hidden=true;setView('reader');document.body.dataset.ready='true';if(startupWarning)toast(startupWarning);}
$('nav').onclick=e=>{const b=e.target.closest('button[data-view]');if(b)setView(b.dataset.view);};
$('library-sort').onchange=renderLibrary;$('library-reset').onclick=()=>{$('library-search').value='';$('library-language').value='';$('library-subject').value='';$('library-sort').value='default';libraryLimit=36;renderLibrary()};
$('juz-jump').onchange=()=>{const a=content.ayahs.find(a=>a.juz===Number($('juz-jump').value));if(a)setSurah(a.surah_id,a.number)};
$('go-page').onclick=()=>{const a=content.ayahs.find(a=>a.page===Number($('page-jump').value));if(a)setSurah(a.surah_id,a.number);else toast('شمارهٔ صفحه باید از ۱ تا ۶۰۴ باشد.')};
$('surah').onchange=()=>setSurah($('surah').value);$('verse').onchange=selectVerse;$('translation').onchange=renderTranslation;
for(const [id,delta]of [['prev',-1],['next',1]])$(id).onclick=()=>{const a=content.ayahs.find(a=>a.id===selected.id+delta);if(a)setSurah(a.surah_id,a.number)};
$('tabs').onclick=e=>{const b=e.target.closest('button[data-tab]');if(!b)return;tab=b.dataset.tab;document.querySelectorAll('#tabs button').forEach(x=>x.classList.toggle('active',x===b));renderResearch();};
$('tafsir-one').onchange=renderResearch;$('tafsir-two').onchange=renderResearch;
$('theme').onclick=()=>{preferences.theme=preferences.dark?'emerald':'night';applyAppearance();remember();};
for(const [id,d]of [['smaller',-1],['larger',1]])$(id).onclick=()=>{preferences.font=Math.min(28,Math.max(15,(Number(preferences.font)||19)+d));applyAppearance();remember();};
$('bookmark').onclick=()=>{const ids=personal.bookmarks.includes(selected.id)?personal.bookmarks.filter(id=>id!==selected.id):[...personal.bookmarks,selected.id];if(persist({...personal,bookmarks:ids}))$('bookmark').textContent=ids.includes(selected.id)?'★ نشان‌شده':'☆ نشان';};
$('note-text').oninput=()=>{if(selected)drafts.set(selected.id,$('note-text').value)};
$('save-note').onclick=()=>{const text=$('note-text').value.trim();if(!text)return toast('ابتدا یادداشت خود را بنویسید.');if(text.length>100000)return toast('یادداشت بیش از حد طولانی است.');const old=personal.notes.find(n=>n.ayahId===selected.id);const note={id:old?.id||crypto.randomUUID(),ayahId:selected.id,text,updatedAt:new Date().toISOString()};if(persist({...personal,notes:[...personal.notes.filter(n=>n.id!==note.id),note]})){drafts.delete(selected.id);toast('یادداشت روی این آیه ذخیره شد.');}};
$('copy').onclick=async()=>{try{await copyText(`${selected.text_original}\n${$('translation-text').textContent}\n${currentLabel()} · ${$('translation').selectedOptions[0].textContent}\nمتن قرآن: Tanzil.net`);toast('متن و ارجاع کپی شد.');}catch{toast('کپی خودکار ممکن نشد؛ متن را انتخاب و Ctrl+C بزنید.');}};
let lastSelection='';document.addEventListener('selectionchange',()=>{const s=window.getSelection();if(s?.toString().trim())lastSelection=s.toString().trim();});$('word-search').onclick=()=>{if(!lastSelection)return toast('ابتدا واژه یا عبارتی از متن را انتخاب کنید.');$('search').value=lastSelection;search();};
$('search-form').onsubmit=e=>{e.preventDefault();search().catch(e=>toast(e.message));};$('library-search').oninput=()=>{libraryLimit=36;renderLibrary();};$('more-books').onclick=()=>{libraryLimit+=36;renderLibrary();};$('notes-search').oninput=renderNotes;
$('export-notes').onclick=()=>download('mansour-research-backup.json',JSON.stringify(personal,null,2),'application/json');
$('export-markdown').onclick=()=>download('mansour-research-notes.md','# یادداشت‌های پژوهشی منصور\n\n'+personal.notes.map(n=>`## ${currentLabel(content.ayahs.find(a=>a.id===n.ayahId))}\n\n${n.text}\n`).join('\n'),'text/markdown;charset=utf-8');
$('import-notes').onclick=()=>$('import-file').click();$('import-file').onchange=async()=>{const file=$('import-file').files[0];try{if(!file)return;if(file.size>20_000_000)throw Error('فایل پشتیبان بیش از حد بزرگ است.');const incoming=validateBackup(JSON.parse(await file.text()));if(persist(mergeBackup(personal,incoming))){renderNotes();toast('پشتیبان با یادداشت‌های فعلی ادغام شد.');}}catch(e){toast(e.message||'فایل نامعتبر است.');}finally{$('import-file').value='';}};
$('mizan-volume').onchange=()=>loadMizanVolume().catch(e=>toast(e.message));$('mizan-page').onchange=renderMizanPage;for(const [id,d]of [['mizan-prev',-1],['mizan-next',1]])$(id).onclick=()=>{const s=$('mizan-page');s.selectedIndex=Math.min(s.options.length-1,Math.max(0,s.selectedIndex+d));renderMizanPage();};
document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key.toLowerCase()==='k'){e.preventDefault();setView('reader');$('search').focus();}if(e.ctrlKey&&e.key.toLowerCase()==='s'&&activeView==='reader'){e.preventDefault();$('save-note').click();}});
init().catch(e=>{$('loading').textContent=`آماده‌سازی انجام نشد: ${e.message}`;document.body.dataset.error=e.message;});
